"use server";

import { prisma } from "@/src/lib/prisma";
import { revalidatePath } from "next/cache";

export async function deleteTask(id: string) {
  try {
    await prisma.task.delete({
      where: { id },
    });
    revalidatePath("/tasks");
    revalidatePath("/");
    return { success: true };
  } catch (error) {
    console.error("Task Delete Error:", error);
    return { success: false, error: "Verwijderen mislukt" };
  }
}

export async function createNewTask(title: string, content: string) {
  try {
    let user = await prisma.user.findFirst();
    if (!user) {
      user = await prisma.user.create({
        data: {
          email: "student@rocmondriaan.nl",
          name: "WorkSpace Student",
          password: "password123"
        }
      });
    }

    await prisma.task.create({
      data: {
        title,
        content,
        userId: user.id,
        status: "TODO",
        priority: "MEDIUM",
        description: "Scrum Document",
        sprint: "1"
      },
    });

    revalidatePath("/tasks");
    revalidatePath("/");
    return { success: true };
  } catch (error) {
    console.error("Task Create Error:", error);
    return { success: false };
  }
}

export async function updateTask(id: string, data: { title: string; content: string }) {
  try {
    await prisma.task.update({
      where: { id },
      data: {
        title: data.title,
        content: data.content,
      },
    });
    revalidatePath("/tasks");
    revalidatePath("/");
    return { success: true };
  } catch (error) {
    return { success: false };
  }
}